  ? '\n[earned-continue-3d tangentSteering3d self-test] OK — all CPU cases passed'
  : `\n[earned-continue-3d tangentSteering3d self-test] FAIL — ${failures} case(s) failed`);
process.exit(failures === 0 ? 0 : 1);

