    // FULL 3D distance. No coordinate is dropped.
    const dTo = dist3d(cur.bodyCentre, target);
    if (dTo <= arriveUnits) { stopReason = 'arrived'; break; }
    if (minDistToTarget && dTo <= minDistToTarget) { stopReason = 'hold-off-distance'; break; }
    // FACE/UP CHANGE -> recalibrate before steering again.
    const staleness = basisStale(basisUp ?? [0, 1, 0], cur.up ?? [0, 1, 0]);
    if (staleness.stale) {
