      log(`local frame changed (${staleness.reason}: ${staleness.faceBefore} -> ${staleness.faceAfter}); recalibrating`);
      await runCalibration(`face-change-${recalibrations}`);
      cur = await cgSnap(page);
      continue;
    }
    const want = [target[0] - cur.bodyCentre[0], target[1] - cur.bodyCentre[1], target[2] - cur.bodyCentre[2]];
    const pick = chooseKey3d(dirs, want, cur.up ?? [0, 1, 0]);
    if (!pick.key) {
      stopReason = `no-usable-key (${pick.reason})`;
      journey.push({ step: 'no-key', burst: bursts, pick, up: cur.up, face: faceLabel(cur.up ?? [0, 1, 0]) });
      break;
    }
    const b = cur.bodyCentre;
    await page.keyboard.down(pick.key); await sleep(400); await page.keyboard.up(pick.key); await sleep(220);
    cur = await cgSnap(page);
    const proj = burstProgress3d({ from: b, to: cur.bodyCentre, target, up: cur.up ?? [0, 1, 0] });
    // Re-measure the pressed key from its ACTUAL displacement, in 3D.
    const movedSample = calibrationSample({ key: pick.key, from: b, to: cur.bodyCentre, up: cur.up ?? [0, 1, 0] });
    if (movedSample.usable) dirs[pick.key] = movedSample.dir3d;
