        avBefore: beforeOfferState?.av ?? null, avAfter: afterOfferState?.av ?? null,
        surveyPhaseBefore: beforeOffer?.survey?.phase ?? null, surveyPhaseAfter: afterOffer?.survey?.phase ?? null
      }),
